```go
package cryptosquare

import (
	"strings"
	"unicode"
)

func Encode(pt string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(pt) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(r)
		}
	}
	msg := b.String()
	n := len(msg)
	if n == 0 {
		return ""
	}
	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c
	chunks := make([]string, c)
	for i := 0; i < c; i++ {
		var sb strings.Builder
		for j := 0; j < r; j++ {
			idx := j*c + i
			if idx < n {
				sb.WriteByte(msg[idx])
			} else {
				sb.WriteByte(' ')
			}
		}
		chunks[i] = sb.String()
	}
	return strings.Join(chunks, " ")
}
```

Using byte length is fine because after normalization everything is lowercase ASCII letters and digits (ASCII). Actually, ToLower on unicode could produce multi-byte runes, but the tests are ASCII. Using strings.Builder and byte indexing is fine for ASCII. To be safe, we could also use runes, but since the spec says "English text", ASCII is fine.

