package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing and removing spaces and
// punctuation), lays it out as a rectangle with c columns and r rows where
// c is the smallest integer with c*c >= len and c - r <= 1, then reads the
// rectangle down the columns, left to right. Chunks are joined with spaces,
// and each of the last chunks is padded with a trailing space if the message
// is short of the perfect rectangle.
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range strings.ToLower(pt) {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(r)
		}
	}
	msg := b.String()
	n := len(msg)
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	chunks := make([]string, c)
	for i := 0; i < c; i++ {
		var sb strings.Builder
		for j := 0; j < r; j++ {
			idx := j*c + i
			if idx < n {
				sb.WriteByte(msg[idx])
			} else {
				sb.WriteByte(' ')
			}
		}
		chunks[i] = sb.String()
	}
	return strings.Join(chunks, " ")
}
